func TestTypedBindingsErrors(t *testing.T) {
	t.Parallel()

	typeErrorContains := func(parts ...string) *func(*testing.T, error) {
		return &(func(t *testing.T, err error) {
			if err == nil {
				t.Errorf("expected error containing %v, got nil", parts)
				return
			}
			for _, part := range parts {
				if !contains(err.Error(), part) {
					t.Errorf("error %q does not contain %q", err.Error(), part)
				}
			}
		})
	}

	tests := []Test{
		{
			Script:       `var x: int64 = "a"`,
			RunErrorFunc: typeErrorContains("type error", "x", "string", "int64"),
		},
		{
			Script:       `var x: int64 = 10; x = "a"`,
			RunErrorFunc: typeErrorContains("type error", "x", "string", "int64"),
		},
		{
			Script:       `var x: string = 10`,
			RunErrorFunc: typeErrorContains("type error", "x", "int64", "string"),
		},
		{
			Script:       `var x: float64 = 10`,
			RunErrorFunc: typeErrorContains("type error", "x", "int64", "float64"),
		},
		{
			Script:       `var x: int = 10`,
			RunErrorFunc: typeErrorContains("type error", "x", "int64", "int"),
		},
		{
			Script:       `var x: int64 = 10; x = 10.0`,
			RunErrorFunc: typeErrorContains("type error", "x", "float64", "int64"),
		},
		{
			Script:       `var x: rune = 10`,
			RunErrorFunc: typeErrorContains("type error", "x", "int64", "int32"),
		},
	}
	runTests(t, tests, nil, &Options{TypedBindings: true})
}

